-- Preserve the workbook wording independently of structured conformance account mappings.
alter table public.ledger_rules add column debit_label text, add column credit_label text;
comment on column public.ledger_rules.debit_label is 'Exact workbook debit wording; null uses the legacy structured catalog labels.';
comment on column public.ledger_rules.credit_label is 'Exact workbook credit wording; null uses the legacy structured catalog labels.';

-- Current chart rows only. Historical catalog rows and account associations remain unchanged.
update public.ledger_rules r set debit_label=s.debit_label, credit_label=s.credit_label
