CREATE OR REPLACE VIEW "public"."v_t_chart" WITH ("security_invoker"='true') AS
 SELECT "r"."rule_code",
    "r"."category",
    "r"."sort_order",
    "r"."trigger_name",
    coalesce("r"."debit_label", "string_agg"("rl"."label", ' • '::"text" ORDER BY "rl"."line_order") FILTER (WHERE ("rl"."side" = 'debit'::"public"."balance_side"))) AS "debit_accounts",
    coalesce("r"."credit_label", "string_agg"("rl"."label", ' • '::"text" ORDER BY "rl"."line_order") FILTER (WHERE ("rl"."side" = 'credit'::"public"."balance_side"))) AS "credit_accounts",
    "r"."reversible",
    "r"."airtable_sources",
    "r"."when_to_post",
    "r"."fin_notes",
    "r"."dev_notes",
    "r"."audit_trail",
    "r"."active"
   FROM ("public"."ledger_rules" "r"
     LEFT JOIN "public"."ledger_rule_lines" "rl" ON (("rl"."rule_code" = "r"."rule_code")))
  GROUP BY "r"."rule_code";
